const m={USD:2,EUR:2,GBP:2,EGP:2,AED:2,SAR:2,JPY:0,KWD:3};function g(r){return m[r.toUpperCase()]??2}function f(r){const t="٠١٢٣٤٥٦٧٨٩";return r.trim().replace(/[٠-٩]/g,n=>String(t.indexOf(n))).replace(/[٬،,\s\u00A0\u202F]/g,"").replace(/٫/g,".")}function p(r,t){const n=g(t),o=f(r);if(!/^-?\d+(\.\d+)?$/.test(o))throw new Error("INVALID_DECIMAL");const c=o.startsWith("-"),[e,i=""]=(c?o.slice(1):o).split(".");if(i.length>n)throw new Error("TOO_MANY_FRACTION_DIGITS");const a=i.padEnd(n,"0"),s=BigInt(e||"0")*10n**BigInt(n)+BigInt(a||"0");return{minorUnits:c?-s:s,currency:t.toUpperCase(),decimals:n}}function I(r,t){const n=BigInt(r),o=n<0n,c=o?-n:n,e=10n**BigInt(t),i=c/e,s=(c%e).toString().padStart(t,"0"),l=t===0?i.toString():`${i.toString()}.${s}`;return o?`-${l}`:l}function D(r,t,n){const o=n.trim()||"USD",c=g(o),e=u(r,o),i=u(t,o);return e==null||i==null?"":I(e+i,c)}function u(r,t){const n=r.trim();if(!n)return 0n;try{return p(n,t).minorUnits}catch{return null}}export{D as c,I as m,f as n,p};
